// Tests for the npm package, run with Node's built-in test runner.
// These are the same five probes the existing verify_under_node.mjs script
// drives, so the package and the raw C ABI script answer identically and a
// regression in one shows up in the other.
//
// Run: node --test crates/kok-wasm/npm/tests/
//
// The honest packet and its forged counterpart are generated by the Rust
// example at crates/kok-wasm/examples/replay_node_hex.rs and written to
// npm/tests/fixtures/ by the packaging script. If the fixtures are absent
// these tests SKIP rather than fail — a missing fixture is a packaging
// problem, not a verifier regression.

import { test, describe } from 'node:test';
import assert from 'node:assert';
import fs from 'node:fs';
import path from 'node:path';
import { init, verifyPacket } from '../index.js';

const FIXTURE_DIR = path.join(import.meta.dirname, 'fixtures');
const HONEST = path.join(FIXTURE_DIR, 'honest.bin');
const FORGED = path.join(FIXTURE_DIR, 'forged.bin');
const SHORT = path.join(FIXTURE_DIR, 'short.bin');

function fixturesPresent() {
  return [HONEST, FORGED, SHORT].every((p) => fs.existsSync(p));
}

describe('kok-wasm npm package', () => {
  test('init() instantiates the module without error', async () => {
    await init();
    // idempotent: a second call returns the same instance, not a second one
    const a = await init();
    const b = await init();
    assert.strictEqual(a, b, 'init() should be idempotent');
  });

  test('verifyPacket returns a number, never undefined or a throw', async () => {
    await init();
    const r = verifyPacket(new Uint8Array(80));
    assert.strictEqual(typeof r, 'number', 'the verifier must return a number');
    assert.ok(r === 0 || r === 1, `expected 0 or 1, got ${r}`);
  });

  test('a packet shorter than the 80-byte header rejects', async () => {
    await init();
    // a zeroed 5-byte buffer is not a packet at all
    assert.strictEqual(verifyPacket(new Uint8Array(5)), 0);
    // the empty packet too
    assert.strictEqual(verifyPacket(new Uint8Array(0)), 0);
  });

  test('the honest packet accepts', { skip: !fixturesPresent() && 'fixtures not generated yet' }, async () => {
    await init();
    const bytes = new Uint8Array(fs.readFileSync(HONEST));
    assert.strictEqual(verifyPacket(bytes), 1, 'an honestly mined packet must accept');
  });

  test('the forged packet rejects', { skip: !fixturesPresent() && 'fixtures not generated yet' }, async () => {
    await init();
    const bytes = new Uint8Array(fs.readFileSync(FORGED));
    assert.strictEqual(verifyPacket(bytes), 0, 'a forged packet must reject');
  });
});
